        "quote": "最近一周在市人民医院的住院病历"
      },
      {
        "event_id": "lite_evt_00087",
        "explanation": "医生称只看到索引，未整合此时已可见的近期介入与胸外科随访摘要。",
        "quote": "系统里有5条就诊记录索引"
      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00134",
        "explanation": "医生给出了部分急诊触发条件，但没有覆盖合同要求的完整红旗集合。",
        "quote": "咯血、突然胸痛、发热"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00134",
        "explanation": "医生根据患者只能请半天假的约束制定了优先顺序。",
        "quote": "如果只能请半天假，建议这样分配"
      },
      {
        "event_id": "lite_evt_00154",
        "explanation": "医生把费用担忧转化为门诊咨询事项。",
        "quote": "预估费用、医保报销比例、押金多少"
      }
    ]
  },
